package com.runeglass.runelite;

import java.util.Objects;

final class SkillObservation
{
	private static final int MAX_SKILL_EXPERIENCE = 200_000_000;

	private final int experience;
	private final int level;
	private final int boostedLevel;

	SkillObservation(int experience, int level, int boostedLevel)
	{
		if (experience < 0 || experience > MAX_SKILL_EXPERIENCE)
		{
			throw new IllegalArgumentException("Skill experience is outside the supported range");
		}
		if (level < 0 || boostedLevel < 0)
		{
			throw new IllegalArgumentException("Skill levels cannot be negative");
		}

		this.experience = experience;
		this.level = level;
		this.boostedLevel = boostedLevel;
	}

	int getExperience()
	{
		return experience;
	}

	int getLevel()
	{
		return level;
	}

	int getBoostedLevel()
	{
		return boostedLevel;
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof SkillObservation))
		{
			return false;
		}

		SkillObservation that = (SkillObservation) other;
		return experience == that.experience
			&& level == that.level
			&& boostedLevel == that.boostedLevel;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(experience, level, boostedLevel);
	}
}

package com.runeglass.runelite;

import java.time.Instant;
import java.util.Arrays;
import java.util.Objects;

public final class SkillsSnapshot
{
	public static final String TYPE = "skills.snapshot.v1";

	private final String type;
	private final String observedAt;
	private final String reason;
	private final int catalogVersion;
	private final long[] experience;
	private final int[] levels;
	private final int[] boostedLevels;

	SkillsSnapshot(
		Instant observedAt,
		SnapshotReason reason,
		long[] experience,
		int[] levels,
		int[] boostedLevels)
	{
		this.type = TYPE;
		this.observedAt = Objects.requireNonNull(observedAt, "observedAt").toString();
		this.reason = Objects.requireNonNull(reason, "reason").wireValue();
		this.catalogVersion = SkillCatalog.VERSION;
		this.experience = copyExperienceVector(experience);
		this.levels = copyLevelVector(levels, "levels");
		this.boostedLevels = copyLevelVector(boostedLevels, "boostedLevels");
	}

	public String getType()
	{
		return type;
	}

	public String getObservedAt()
	{
		return observedAt;
	}

	public String getReason()
	{
		return reason;
	}

	public int getCatalogVersion()
	{
		return catalogVersion;
	}

	public long[] getExperience()
	{
		return Arrays.copyOf(experience, experience.length);
	}

	public int[] getLevels()
	{
		return Arrays.copyOf(levels, levels.length);
	}

	public int[] getBoostedLevels()
	{
		return Arrays.copyOf(boostedLevels, boostedLevels.length);
	}

	private static long[] copyExperienceVector(long[] vector)
	{
		Objects.requireNonNull(vector, "experience");
		if (vector.length != SkillCatalog.VECTOR_SIZE)
		{
			throw new IllegalArgumentException("Experience vector must match the V1 catalog");
		}
		return Arrays.copyOf(vector, vector.length);
	}

	private static int[] copyLevelVector(int[] vector, String name)
	{
		Objects.requireNonNull(vector, name);
		if (vector.length != SkillCatalog.VECTOR_SIZE)
		{
			throw new IllegalArgumentException(name + " vector must match the V1 catalog");
		}
		return Arrays.copyOf(vector, vector.length);
	}
}

package com.runeglass.runelite;

import java.time.Instant;
import java.util.EnumMap;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import net.runelite.api.Skill;

public final class SkillsSnapshotReducer
{
	private final Map<Skill, SkillObservation> observations = new EnumMap<>(Skill.class);
	private boolean dirty;

	public boolean accept(Skill skill, int experience, int level, int boostedLevel)
	{
		Objects.requireNonNull(skill, "skill");
		if (!SkillCatalog.contains(skill))
		{
			throw new IllegalArgumentException("Skill is not part of the V1 catalog");
		}

		SkillObservation next = new SkillObservation(experience, level, boostedLevel);
		SkillObservation previous = observations.put(skill, next);
		boolean changed = !next.equals(previous);
		dirty = dirty || changed;
		return changed;
	}

	public boolean isComplete()
	{
		return observations.size() == SkillCatalog.trainableSkills().size();
	}

	public boolean hasChanges()
	{
		return dirty;
	}

	public Optional<SkillsSnapshot> takeSnapshot(Instant observedAt, SnapshotReason reason)
	{
		if (!isComplete() || !dirty)
		{
			return Optional.empty();
		}
		return buildSnapshot(observedAt, reason);
	}

	public Optional<SkillsSnapshot> takeCompleteSnapshot(Instant observedAt, SnapshotReason reason)
	{
		if (!isComplete())
		{
			return Optional.empty();
		}
		return buildSnapshot(observedAt, reason);
	}

	private Optional<SkillsSnapshot> buildSnapshot(Instant observedAt, SnapshotReason reason)
	{
		Objects.requireNonNull(observedAt, "observedAt");
		Objects.requireNonNull(reason, "reason");

		long[] experience = new long[SkillCatalog.VECTOR_SIZE];
		int[] levels = new int[SkillCatalog.VECTOR_SIZE];
		int[] boostedLevels = new int[SkillCatalog.VECTOR_SIZE];

		int index = 1;
		for (Skill skill : SkillCatalog.trainableSkills())
		{
			SkillObservation observation = observations.get(skill);
			experience[index] = observation.getExperience();
			levels[index] = observation.getLevel();
			boostedLevels[index] = observation.getBoostedLevel();

			experience[0] += observation.getExperience();
			levels[0] += observation.getLevel();
			boostedLevels[0] += observation.getBoostedLevel();
			index++;
		}

		dirty = false;
		return Optional.of(new SkillsSnapshot(
			observedAt,
			reason,
			experience,
			levels,
			boostedLevels));
	}

	public void reset()
	{
		observations.clear();
		dirty = false;
	}
}

package com.runeglass.runelite;

import java.time.Duration;
import java.time.Instant;
import java.util.Objects;
import java.util.Optional;
import net.runelite.api.Skill;

public final class SkillsSyncSession
{
	public static final Duration CHANGE_DEBOUNCE = Duration.ofSeconds(30);
	public static final Duration NORMAL_UPLOAD_WINDOW = Duration.ofMinutes(5);
	public static final Duration COVERAGE_HEARTBEAT_WINDOW = Duration.ofMinutes(10);

	private final SkillsSnapshotReducer reducer = new SkillsSnapshotReducer();

	private boolean active;
	private boolean baselineEmitted;
	private Instant firstDirtyAt;
	private Instant lastEmissionAt;

	public void start()
	{
		reducer.reset();
		active = true;
		baselineEmitted = false;
		firstDirtyAt = null;
		lastEmissionAt = null;
	}

	public Optional<SkillsSnapshot> accept(
		Skill skill,
		int experience,
		int level,
		int boostedLevel,
		Instant observedAt)
	{
		Objects.requireNonNull(observedAt, "observedAt");
		if (!active)
		{
			return Optional.empty();
		}

		boolean changed = reducer.accept(skill, experience, level, boostedLevel);
		if (!changed)
		{
			return Optional.empty();
		}

		if (!baselineEmitted && reducer.isComplete())
		{
			return emit(observedAt, SnapshotReason.LOGIN_BASELINE);
		}

		if (baselineEmitted && firstDirtyAt == null)
		{
			firstDirtyAt = observedAt;
		}

		return Optional.empty();
	}

	public Optional<SkillsSnapshot> poll(Instant observedAt)
	{
		Objects.requireNonNull(observedAt, "observedAt");
		if (!active || !baselineEmitted)
		{
			return Optional.empty();
		}

		if (reducer.hasChanges() && firstDirtyAt != null)
		{
			Instant debouncedAt = firstDirtyAt.plus(CHANGE_DEBOUNCE);
			Instant windowOpensAt = lastEmissionAt.plus(NORMAL_UPLOAD_WINDOW);
			if (observedAt.isBefore(debouncedAt) || observedAt.isBefore(windowOpensAt))
			{
				return Optional.empty();
			}
			return emit(observedAt, SnapshotReason.CHANGE_CHECKPOINT);
		}

		if (observedAt.isBefore(lastEmissionAt.plus(COVERAGE_HEARTBEAT_WINDOW)))
		{
			return Optional.empty();
		}
		return emitComplete(observedAt, SnapshotReason.COVERAGE_HEARTBEAT);
	}

	public Optional<SkillsSnapshot> stop(Instant observedAt, SnapshotReason reason)
	{
		Objects.requireNonNull(observedAt, "observedAt");
		Objects.requireNonNull(reason, "reason");
		if (reason != SnapshotReason.LOGOUT_FLUSH && reason != SnapshotReason.PROFILE_SWITCH)
		{
			throw new IllegalArgumentException("A session can only stop for logout or profile switch");
		}

		Optional<SkillsSnapshot> snapshot = Optional.empty();
		if (active && baselineEmitted)
		{
			snapshot = reducer.takeCompleteSnapshot(observedAt, reason);
		}

		cancel();
		return snapshot;
	}

	public Optional<SkillsSnapshot> manualSync(Instant observedAt)
	{
		Objects.requireNonNull(observedAt, "observedAt");
		if (!active || !baselineEmitted)
		{
			return Optional.empty();
		}
		Optional<SkillsSnapshot> snapshot = reducer.takeCompleteSnapshot(
			observedAt,
			SnapshotReason.MANUAL_SYNC);
		if (snapshot.isPresent())
		{
			firstDirtyAt = null;
			lastEmissionAt = observedAt;
		}
		return snapshot;
	}

	public void cancel()
	{
		reducer.reset();
		active = false;
		baselineEmitted = false;
		firstDirtyAt = null;
		lastEmissionAt = null;
	}

	public boolean isActive()
	{
		return active;
	}

	private Optional<SkillsSnapshot> emit(Instant observedAt, SnapshotReason reason)
	{
		Optional<SkillsSnapshot> snapshot = reducer.takeSnapshot(observedAt, reason);
		if (snapshot.isPresent())
		{
			baselineEmitted = true;
			firstDirtyAt = null;
			lastEmissionAt = observedAt;
		}
		return snapshot;
	}

	private Optional<SkillsSnapshot> emitComplete(Instant observedAt, SnapshotReason reason)
	{
		Optional<SkillsSnapshot> snapshot = reducer.takeCompleteSnapshot(observedAt, reason);
		if (snapshot.isPresent())
		{
			baselineEmitted = true;
			firstDirtyAt = null;
			lastEmissionAt = observedAt;
		}
		return snapshot;
	}
}

package com.runeglass.runelite;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.math.BigInteger;
import java.time.Clock;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.LongSupplier;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

final class SnapshotClient
{
	private static final String BATCH_PATH = "runelite/v1/batches";
	private static final int MAX_PENDING_SNAPSHOTS = 8;
	private static final int MAX_RESPONSE_CHARACTERS = 8 * 1_024;
	private static final int MAX_RETRY_AFTER_SECONDS = 300;
	private static final int MAX_NEXT_UPLOAD_SECONDS = 3_600;
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	interface Listener
	{
		void onUploading(int recordCount);

		void onAccepted(Instant serverTime);

		void onRetryScheduled();

		void onFailure(Failure failure);

		default void onNextSequenceChanged(BigInteger nextSequence)
		{
		}

		default void onSessionDrained()
		{
		}
	}

	enum Failure
	{
		INVALID_CONNECTION,
		BINDING_MISMATCH,
		UNSUPPORTED_PROFILE,
		REJECTED_BATCH,
		PROTOCOL_ERROR
	}

	private final Object lock = new Object();
	private final OkHttpClient httpClient;
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final HttpUrl baseUrl;
	private final Clock clock;
	private final int baseRetrySeconds;
	private final LongSupplier retryJitterMillis;
	private final Deque<SkillsSnapshot> pending = new ArrayDeque<>();

	private long generation;
	private PairingClient.Credentials credentials;
	private SyncContext context;
	private Listener listener;
	private BigInteger nextSequence = BigInteger.ONE;
	private DurableSnapshotQueue durableQueue;
	private Instant nextUploadAt = Instant.EPOCH;
	private InFlightBatch inFlight;
	private Call activeCall;
	private ScheduledFuture<?> scheduledDispatch;
	private int retryAttempt;
	private boolean finalizingSession;
	private boolean closingAfterFlush;
	private boolean forceNextDispatch;

	static SnapshotClient create(
		OkHttpClient httpClient,
		Gson gson,
		ScheduledExecutorService executor)
	{
		return new SnapshotClient(
			httpClient,
			gson,
			executor,
			Objects.requireNonNull(
				HttpUrl.parse(PairingClient.BASE_URL),
				"RuneGlass base URL"),
			Clock.systemUTC(),
			5,
			() -> java.util.concurrent.ThreadLocalRandom.current().nextLong(1_001));
	}

	SnapshotClient(
		OkHttpClient httpClient,
		Gson gson,
		ScheduledExecutorService executor,
		HttpUrl baseUrl,
		Clock clock,
		int baseRetrySeconds,
		LongSupplier retryJitterMillis)
	{
		this.httpClient = Objects.requireNonNull(httpClient, "httpClient");
		this.gson = Objects.requireNonNull(gson, "gson");
		this.executor = Objects.requireNonNull(executor, "executor");
		this.baseUrl = Objects.requireNonNull(baseUrl, "baseUrl");
		this.clock = Objects.requireNonNull(clock, "clock");
		if (baseRetrySeconds <= 0 || baseRetrySeconds > MAX_RETRY_AFTER_SECONDS)
		{
			throw new IllegalArgumentException("Invalid base retry interval");
		}
		this.baseRetrySeconds = baseRetrySeconds;
		this.retryJitterMillis = Objects.requireNonNull(retryJitterMillis, "retryJitterMillis");
	}

	boolean connect(
		PairingClient.Credentials nextCredentials,
		SyncContext nextContext,
		BigInteger persistedNextSequence,
		DurableSnapshotQueue nextDurableQueue,
		Listener nextListener)
	{
		Objects.requireNonNull(nextCredentials, "credentials");
		Objects.requireNonNull(nextContext, "context");
		Objects.requireNonNull(persistedNextSequence, "persistedNextSequence");
		Objects.requireNonNull(nextDurableQueue, "durableQueue");
		Objects.requireNonNull(nextListener, "listener");
		if (persistedNextSequence.signum() <= 0
			|| persistedNextSequence.toString().length() > 20
			|| nextDurableQueue.getLoadStatus() != DurableSnapshotQueue.LoadStatus.READY)
		{
			nextListener.onFailure(Failure.REJECTED_BATCH);
			return false;
		}
		synchronized (lock)
		{
			if (finalizingSession || activeCall != null || scheduledDispatch != null)
			{
				return false;
			}
			generation++;
			resetSessionLocked();
			credentials = nextCredentials;
			context = nextContext;
			listener = nextListener;
			durableQueue = nextDurableQueue;
			nextSequence = nextSequence.max(persistedNextSequence);
			nextUploadAt = Instant.EPOCH;
			closingAfterFlush = false;
		}
		if (!validateRestoredQueue())
		{
			failCurrent(Failure.REJECTED_BATCH);
			return false;
		}
		dispatchAsync();
		return true;
	}

	boolean publish(SkillsSnapshot snapshot)
	{
		return publish(snapshot, false);
	}

	boolean publishImmediately(SkillsSnapshot snapshot)
	{
		return publish(snapshot, true);
	}

	private boolean publish(SkillsSnapshot snapshot, boolean immediate)
	{
		Objects.requireNonNull(snapshot, "snapshot");
		synchronized (lock)
		{
			if (credentials == null || context == null || listener == null)
			{
				return false;
			}
			if (finalizingSession || closingAfterFlush)
			{
				return false;
			}
			enqueueSnapshotLocked(snapshot);
			if (immediate)
			{
				forceNextDispatch = true;
				nextUploadAt = Instant.EPOCH;
				cancelScheduledDispatchLocked();
			}
		}
		dispatchAsync();
		return true;
	}

	boolean finishSession(SkillsSnapshot finalSnapshot)
	{
		Objects.requireNonNull(finalSnapshot, "finalSnapshot");
		return finishSessionInternal(finalSnapshot);
	}

	boolean finishSession()
	{
		return finishSessionInternal(null);
	}

	private boolean finishSessionInternal(SkillsSnapshot finalSnapshot)
	{
		final Listener drainedListener;
		synchronized (lock)
		{
			if (credentials == null || context == null || listener == null)
			{
				return false;
			}
			if (!finalizingSession && finalSnapshot != null)
			{
				enqueueSnapshotLocked(finalSnapshot);
			}
			finalizingSession = true;
			nextUploadAt = Instant.EPOCH;
			cancelScheduledDispatchLocked();
			drainedListener = drainSessionIfIdleLocked();
		}
		if (drainedListener != null)
		{
			drainedListener.onSessionDrained();
		}
		else
		{
			dispatchAsync();
		}
		return true;
	}

	void closeAfterFlush()
	{
		boolean alreadyDrained = false;
		synchronized (lock)
		{
			closingAfterFlush = true;
			finalizingSession = true;
			nextUploadAt = Instant.EPOCH;
			cancelScheduledDispatchLocked();
			if (activeCall == null && inFlight == null && pending.isEmpty())
			{
				generation++;
				resetLocked();
				alreadyDrained = true;
			}
		}
		if (!alreadyDrained)
		{
			dispatchAsync();
		}
	}

	boolean isFinishingSession()
	{
		synchronized (lock)
		{
			return finalizingSession || closingAfterFlush;
		}
	}

	void cancel()
	{
		synchronized (lock)
		{
			generation++;
			resetLocked();
		}
	}

	void discard()
	{
		final DurableSnapshotQueue queue;
		synchronized (lock)
		{
			queue = durableQueue;
			generation++;
			resetLocked();
		}
		if (queue != null)
		{
			try
			{
				executor.execute(() ->
				{
					try
					{
						queue.clear();
					}
					catch (IOException ignored)
					{
					}
				});
			}
			catch (RuntimeException ignored)
			{
			}
		}
	}

	private void dispatch()
	{
		final SequenceAdvance sequenceAdvance = persistPending();
		if (sequenceAdvance.listener != null)
		{
			sequenceAdvance.listener.onNextSequenceChanged(sequenceAdvance.nextSequence);
		}
		if (sequenceAdvance.failure != null)
		{
			fail(sequenceAdvance.generation, sequenceAdvance.failure);
			return;
		}

		final long requestGeneration;
		final Call call;
		final Listener currentListener;
		final int recordCount;
		final Listener drainedListener;
		Failure preparationFailure = null;

		synchronized (lock)
		{
			if (credentials == null
				|| context == null
				|| listener == null
				|| durableQueue == null
				|| activeCall != null
				|| scheduledDispatch != null)
			{
				return;
			}

			if (forceNextDispatch && inFlight == null && durableQueue.size() > 0)
			{
				nextUploadAt = Instant.EPOCH;
			}
			long cooldownMillis = nextUploadAt.toEpochMilli() - clock.millis();
			if (inFlight == null && cooldownMillis > 0 && durableQueue.size() > 0)
			{
				if (scheduleLocked(generation, cooldownMillis))
				{
					return;
				}
				preparationFailure = Failure.PROTOCOL_ERROR;
			}

			if (preparationFailure == null && inFlight == null)
			{
				Optional<DurableSnapshotQueue.Entry> queued = durableQueue.peek();
				if (!queued.isPresent())
				{
					drainedListener = drainSessionIfIdleLocked();
					requestGeneration = generation;
					call = null;
					currentListener = listener;
					recordCount = 0;
				}
				else
				{
					try
					{
						inFlight = queuedBatch(queued.get(), credentials.getConnectionId());
					}
					catch (RuntimeException exception)
					{
						preparationFailure = Failure.PROTOCOL_ERROR;
					}
					drainedListener = null;
					requestGeneration = generation;
					if (preparationFailure == null)
					{
						forceNextDispatch = false;
						Request request = request(inFlight.body, credentials.getRawCredential());
						call = httpClient.newCall(request);
						activeCall = call;
						currentListener = listener;
						recordCount = inFlight.recordCount;
					}
					else
					{
						call = null;
						currentListener = listener;
						recordCount = 0;
					}
				}
			}
			else if (preparationFailure != null)
			{
				requestGeneration = generation;
				call = null;
				currentListener = listener;
				recordCount = 0;
				drainedListener = null;
			}
			else if (inFlight != null)
			{
				requestGeneration = generation;
				Request request = request(inFlight.body, credentials.getRawCredential());
				call = httpClient.newCall(request);
				activeCall = call;
				currentListener = listener;
				recordCount = inFlight.recordCount;
				drainedListener = null;
			}
			else
			{
				requestGeneration = generation;
				call = null;
				currentListener = listener;
				recordCount = 0;
				drainedListener = null;
			}
		}

		if (drainedListener != null)
		{
			drainedListener.onSessionDrained();
			return;
		}

		if (preparationFailure != null)
		{
			fail(requestGeneration, preparationFailure);
			return;
		}
		if (call == null)
		{
			return;
		}

		try
		{
			call.enqueue(new Callback()
			{
				@Override
				public void onFailure(Call ignored, IOException exception)
				{
					retry(requestGeneration, null);
				}

				@Override
				public void onResponse(Call ignored, Response response)
				{
					try (Response closedResponse = response)
					{
						handleResponse(requestGeneration, closedResponse);
					}
					catch (IOException | RuntimeException exception)
					{
						fail(requestGeneration, Failure.PROTOCOL_ERROR);
					}
				}
			});
		}
		catch (RuntimeException exception)
		{
			retry(requestGeneration, null);
			return;
		}
		currentListener.onUploading(recordCount);
	}

	private SequenceAdvance persistPending()
	{
		synchronized (lock)
		{
			if (credentials == null || context == null || listener == null || durableQueue == null)
			{
				return SequenceAdvance.none(generation);
			}
			BigInteger advancedTo = null;
			try
			{
				while (!pending.isEmpty())
				{
					List<SkillsSnapshot> records = new ArrayList<>(MAX_PENDING_SNAPSHOTS);
					for (SkillsSnapshot snapshot : pending)
					{
						if (records.size() == MAX_PENDING_SNAPSHOTS)
						{
							break;
						}
						records.add(snapshot);
					}
					String batchId = java.util.UUID.randomUUID().toString();
					SyncBatch batch = new SyncBatch(
						batchId,
						credentials.getConnectionId(),
						nextSequence.toString(),
						clock.instant(),
						context,
						records);
					DurableSnapshotQueue.EnqueueResult result = durableQueue.enqueue(
						batchId,
						gson.toJson(batch));
					if (!result.wasAdded()
						|| result.getExpiredDropped() != 0
						|| result.getCapacityDropped() != 0)
					{
						throw new IOException("RuneGlass queue rejected a new batch");
					}
					for (int index = 0; index < records.size(); index++)
					{
						pending.removeFirst();
					}
					nextSequence = nextSequence.add(BigInteger.ONE);
					advancedTo = nextSequence;
				}
			}
			catch (IOException | RuntimeException exception)
			{
				return SequenceAdvance.failure(generation, Failure.PROTOCOL_ERROR);
			}
			return advancedTo == null
				? SequenceAdvance.none(generation)
				: SequenceAdvance.advanced(generation, listener, advancedTo);
		}
	}

	private void handleResponse(long requestGeneration, Response response) throws IOException
	{
		if (response.code() == 200)
		{
			handleAccepted(requestGeneration, response);
			return;
		}
		if (response.code() == 429 || response.code() == 500 || response.code() == 503)
		{
			retry(requestGeneration, retryAfterSeconds(response));
			return;
		}

		JsonObject body = ProtocolJson.readObject(response, MAX_RESPONSE_CHARACTERS);
		if (!ProtocolJson.hasExactKeys(body, "protocolVersion", "error")
			|| ProtocolJson.intValue(body, "protocolVersion") != 1)
		{
			fail(requestGeneration, Failure.PROTOCOL_ERROR);
			return;
		}
		String error = ProtocolJson.stringValue(body, "error");
		if (response.code() == 401 && "invalid_connection_credential".equals(error))
		{
			fail(requestGeneration, Failure.INVALID_CONNECTION);
		}
		else if (response.code() == 403
			&& ("binding_mismatch".equals(error) || "scope_denied".equals(error)))
		{
			fail(requestGeneration, Failure.BINDING_MISMATCH);
		}
		else if (response.code() == 422 && "unsupported_profile".equals(error))
		{
			fail(requestGeneration, Failure.UNSUPPORTED_PROFILE);
		}
		else if (response.code() == 400
			|| response.code() == 409
			|| response.code() == 413
			|| response.code() == 422)
		{
			fail(requestGeneration, Failure.REJECTED_BATCH);
		}
		else
		{
			fail(requestGeneration, Failure.PROTOCOL_ERROR);
		}
	}

	private void handleAccepted(long requestGeneration, Response response) throws IOException
	{
		JsonObject body = ProtocolJson.readObject(response, MAX_RESPONSE_CHARACTERS);
		if (!ProtocolJson.hasExactKeys(
			body,
			"protocolVersion",
			"status",
			"acceptedSequence",
			"serverTime",
			"nextUploadAfterSeconds")
			|| ProtocolJson.intValue(body, "protocolVersion") != 1)
		{
			fail(requestGeneration, Failure.PROTOCOL_ERROR);
			return;
		}
		String status = ProtocolJson.stringValue(body, "status");
		String acceptedSequence = ProtocolJson.stringValue(body, "acceptedSequence");
		int nextUploadAfterSeconds = ProtocolJson.intValue(
			body,
			"nextUploadAfterSeconds");
		final Instant serverTime;
		try
		{
			serverTime = Instant.parse(ProtocolJson.stringValue(body, "serverTime"));
		}
		catch (DateTimeParseException exception)
		{
			fail(requestGeneration, Failure.PROTOCOL_ERROR);
			return;
		}

		final Listener currentListener;
		final Listener drainedListener;
		synchronized (lock)
		{
			if (requestGeneration != generation || inFlight == null)
			{
				return;
			}
			if (!("accepted".equals(status) || "duplicate".equals(status))
				|| !inFlight.sequence.equals(acceptedSequence)
				|| nextUploadAfterSeconds <= 0
				|| nextUploadAfterSeconds > MAX_NEXT_UPLOAD_SECONDS)
			{
				currentListener = null;
				drainedListener = null;
			}
			else
			{
				if (durableQueue == null)
				{
					currentListener = null;
					drainedListener = null;
					return;
				}
				durableQueue.acknowledge(inFlight.batchId);
				activeCall = null;
				inFlight = null;
				nextUploadAt = clock.instant().plusSeconds(nextUploadAfterSeconds);
				if (finalizingSession)
				{
					nextUploadAt = Instant.EPOCH;
				}
				retryAttempt = 0;
				currentListener = listener;
				drainedListener = drainSessionIfIdleLocked();
			}
		}
		if (currentListener == null)
		{
			fail(requestGeneration, Failure.PROTOCOL_ERROR);
			return;
		}
		currentListener.onAccepted(serverTime);
		if (drainedListener != null)
		{
			drainedListener.onSessionDrained();
		}
		else
		{
			dispatch();
		}
	}

	private void retry(long requestGeneration, Integer serverDelaySeconds)
	{
		final Listener currentListener;
		final boolean scheduled;
		final boolean closed;
		synchronized (lock)
		{
			if (requestGeneration != generation || inFlight == null)
			{
				return;
			}
			activeCall = null;
			if (closingAfterFlush)
			{
				currentListener = listener;
				generation++;
				resetLocked();
				scheduled = true;
				closed = true;
			}
			else
			{
				retryAttempt++;
				int exponent = Math.min(retryAttempt - 1, 6);
				int backoffSeconds = Math.min(
					MAX_RETRY_AFTER_SECONDS,
					baseRetrySeconds * (1 << exponent));
				int delaySeconds = serverDelaySeconds == null
					? backoffSeconds
					: Math.max(backoffSeconds, serverDelaySeconds);
				long jitterMillis = Math.max(0L, Math.min(1_000L, retryJitterMillis.getAsLong()));
				scheduled = scheduleLocked(
					requestGeneration,
					TimeUnit.SECONDS.toMillis(delaySeconds) + jitterMillis);
				currentListener = listener;
				closed = false;
			}
		}
		if (closed)
		{
			if (currentListener != null)
			{
				currentListener.onSessionDrained();
			}
			return;
		}
		if (!scheduled)
		{
			fail(requestGeneration, Failure.PROTOCOL_ERROR);
			return;
		}
		currentListener.onRetryScheduled();
	}

	private boolean scheduleLocked(long requestGeneration, long delayMillis)
	{
		try
		{
			scheduledDispatch = executor.schedule(() ->
			{
				synchronized (lock)
				{
					if (requestGeneration != generation)
					{
						return;
					}
					scheduledDispatch = null;
				}
				dispatch();
			}, Math.max(0L, delayMillis), TimeUnit.MILLISECONDS);
			return true;
		}
		catch (RuntimeException exception)
		{
			return false;
		}
	}

	private void fail(long requestGeneration, Failure failure)
	{
		final Listener currentListener;
		final DurableSnapshotQueue queue;
		synchronized (lock)
		{
			if (requestGeneration != generation)
			{
				return;
			}
			currentListener = listener;
			queue = durableQueue;
			generation++;
			resetLocked();
		}
		if (queue != null)
		{
			try
			{
				queue.clear();
			}
			catch (IOException ignored)
			{
			}
		}
		if (currentListener != null)
		{
			currentListener.onFailure(failure);
		}
	}

	private void resetLocked()
	{
		if (activeCall != null)
		{
			activeCall.cancel();
			activeCall = null;
		}
		cancelScheduledDispatchLocked();
		pending.clear();
		credentials = null;
		context = null;
		listener = null;
		inFlight = null;
		durableQueue = null;
		nextSequence = BigInteger.ONE;
		nextUploadAt = Instant.EPOCH;
		retryAttempt = 0;
		finalizingSession = false;
		closingAfterFlush = false;
		forceNextDispatch = false;
	}

	private void resetSessionLocked()
	{
		cancelScheduledDispatchLocked();
		pending.clear();
		context = null;
		listener = null;
		inFlight = null;
		nextUploadAt = Instant.EPOCH;
		retryAttempt = 0;
		finalizingSession = false;
		closingAfterFlush = false;
		forceNextDispatch = false;
	}

	private void enqueueSnapshotLocked(SkillsSnapshot snapshot)
	{
		pending.addLast(snapshot);
	}

	private void cancelScheduledDispatchLocked()
	{
		if (scheduledDispatch != null)
		{
			scheduledDispatch.cancel(false);
			scheduledDispatch = null;
		}
	}

	private Listener drainSessionIfIdleLocked()
	{
		if (!finalizingSession
			|| activeCall != null
			|| inFlight != null
			|| !pending.isEmpty()
			|| (durableQueue != null && durableQueue.size() > 0))
		{
			return null;
		}
		Listener drainedListener = listener;
		generation++;
		if (closingAfterFlush)
		{
			resetLocked();
		}
		else
		{
			resetSessionLocked();
		}
		return drainedListener;
	}

	private Request request(String body, String rawCredential)
	{
		HttpUrl url = Objects.requireNonNull(baseUrl.resolve(BATCH_PATH), "RuneGlass batch route");
		return new Request.Builder()
			.url(url)
			.header("Accept", "application/json")
			.header("Authorization", "Bearer " + rawCredential)
			.post(RequestBody.create(JSON, body))
			.build();
	}

	private static Integer retryAfterSeconds(Response response)
	{
		String header = response.header("Retry-After");
		if (header == null || !header.matches("^[1-9][0-9]{0,2}$"))
		{
			return null;
		}
		try
		{
			int value = Integer.parseInt(header);
			return value <= MAX_RETRY_AFTER_SECONDS ? value : null;
		}
		catch (NumberFormatException exception)
		{
			return null;
		}
	}

	private void dispatchAsync()
	{
		final long requestGeneration;
		synchronized (lock)
		{
			requestGeneration = generation;
		}
		try
		{
			executor.execute(() ->
			{
				synchronized (lock)
				{
					if (requestGeneration != generation)
					{
						return;
					}
				}
				dispatch();
			});
		}
		catch (RuntimeException exception)
		{
			fail(requestGeneration, Failure.PROTOCOL_ERROR);
		}
	}

	private boolean validateRestoredQueue()
	{
		synchronized (lock)
		{
			if (credentials == null || durableQueue == null)
			{
				return false;
			}
			BigInteger previous = null;
			try
			{
				for (DurableSnapshotQueue.Entry entry : durableQueue.pendingEntries())
				{
					InFlightBatch batch = queuedBatch(entry, credentials.getConnectionId());
					BigInteger sequence = new BigInteger(batch.sequence);
					if (previous != null && !sequence.equals(previous.add(BigInteger.ONE)))
					{
						return false;
					}
					previous = sequence;
				}
				if (previous != null)
				{
					nextSequence = nextSequence.max(previous.add(BigInteger.ONE));
				}
				return true;
			}
			catch (RuntimeException exception)
			{
				return false;
			}
		}
	}

	private void failCurrent(Failure failure)
	{
		final long currentGeneration;
		synchronized (lock)
		{
			currentGeneration = generation;
		}
		fail(currentGeneration, failure);
	}

	private static InFlightBatch queuedBatch(
		DurableSnapshotQueue.Entry entry,
		String expectedConnectionId)
	{
		JsonObject body = new JsonParser().parse(entry.getPayload()).getAsJsonObject();
		if (!ProtocolJson.hasExactKeys(
			body,
			"protocolVersion",
			"batchId",
			"connectionId",
			"sessionId",
			"sequence",
			"capturedAt",
			"client",
			"character",
			"records")
			|| ProtocolJson.intValue(body, "protocolVersion") != 1)
		{
			throw new IllegalArgumentException("Invalid queued RuneGlass batch");
		}
		String batchId = ProtocolJson.stringValue(body, "batchId");
		String connectionId = ProtocolJson.stringValue(body, "connectionId");
		String sequence = ProtocolJson.stringValue(body, "sequence");
		int recordCount = body.getAsJsonArray("records").size();
		if (!entry.getRecordId().equals(batchId)
			|| !expectedConnectionId.equals(connectionId)
			|| !sequence.matches("^[1-9][0-9]{0,19}$")
			|| recordCount < 1
			|| recordCount > MAX_PENDING_SNAPSHOTS)
		{
			throw new IllegalArgumentException("Invalid queued RuneGlass batch binding");
		}
		java.util.UUID.fromString(batchId);
		return new InFlightBatch(batchId, sequence, entry.getPayload(), recordCount);
	}

	private static final class SequenceAdvance
	{
		private final long generation;
		private final Listener listener;
		private final BigInteger nextSequence;
		private final Failure failure;

		private SequenceAdvance(
			long generation,
			Listener listener,
			BigInteger nextSequence,
			Failure failure)
		{
			this.generation = generation;
			this.listener = listener;
			this.nextSequence = nextSequence;
			this.failure = failure;
		}

		private static SequenceAdvance none(long generation)
		{
			return new SequenceAdvance(generation, null, null, null);
		}

		private static SequenceAdvance advanced(
			long generation,
			Listener listener,
			BigInteger nextSequence)
		{
			return new SequenceAdvance(generation, listener, nextSequence, null);
		}

		private static SequenceAdvance failure(
			long generation,
			Failure failure)
		{
			return new SequenceAdvance(generation, null, null, failure);
		}
	}

	private static final class InFlightBatch
	{
		private final String batchId;
		private final String sequence;
		private final String body;
		private final int recordCount;

		private InFlightBatch(String batchId, String sequence, String body, int recordCount)
		{
			this.batchId = batchId;
			this.sequence = sequence;
			this.body = body;
			this.recordCount = recordCount;
		}
	}
}

package com.runeglass.runelite;

public enum SnapshotReason
{
	LOGIN_BASELINE("login_baseline"),
	CHANGE_CHECKPOINT("change_checkpoint"),
	COVERAGE_HEARTBEAT("coverage_heartbeat"),
	LOGOUT_FLUSH("logout_flush"),
	PROFILE_SWITCH("profile_switch"),
	MANUAL_SYNC("manual_sync"),
	SCHEMA_RECONCILE("schema_reconcile");

	private final String wireValue;

	SnapshotReason(String wireValue)
	{
		this.wireValue = wireValue;
	}

	public String wireValue()
	{
		return wireValue;
	}
}

package com.runeglass.runelite;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

final class SyncBatch
{
	private final int protocolVersion = 1;
	private final String batchId;
	private final String connectionId;
	private final String sessionId;
	private final String sequence;
	private final String capturedAt;
	private final ClientMetadata client;
	private final CharacterMetadata character;
	private final List<SkillsSnapshot> records;

	SyncBatch(
		String batchId,
		String connectionId,
		String sequence,
		Instant capturedAt,
		SyncContext context,
		List<SkillsSnapshot> records)
	{
		this.batchId = Objects.requireNonNull(batchId, "batchId");
		this.connectionId = Objects.requireNonNull(connectionId, "connectionId");
		this.sessionId = Objects.requireNonNull(context, "context").getSessionId();
		this.sequence = Objects.requireNonNull(sequence, "sequence");
		this.capturedAt = Objects.requireNonNull(capturedAt, "capturedAt").toString();
		this.client = new ClientMetadata(context);
		this.character = new CharacterMetadata(context);
		if (records.isEmpty() || records.size() > 8)
		{
			throw new IllegalArgumentException("A V1 batch requires one to eight records");
		}
		this.records = Collections.unmodifiableList(new ArrayList<>(records));
	}

	private static final class ClientMetadata
	{
		private final String pluginVersion;
		private final String runeliteVersion;
		private final int gameRevision;

		private ClientMetadata(SyncContext context)
		{
			this.pluginVersion = context.getPluginVersion();
			this.runeliteVersion = context.getRuneLiteVersion();
			this.gameRevision = context.getGameRevision();
		}
	}

	private static final class CharacterMetadata
	{
		private final String displayName;
		private final String accountType;
		private final String profileType;

		private CharacterMetadata(SyncContext context)
		{
			this.displayName = context.getDisplayName();
			this.accountType = context.getAccountType();
			this.profileType = context.getProfileType();
		}
	}
}

package com.runeglass.runelite;

import java.util.EnumSet;
import java.util.Objects;
import java.util.UUID;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldType;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.RuneLiteProperties;

final class SyncContext
{
	static final String PLUGIN_VERSION = "1.2.0";

	private static final Pattern DISPLAY_NAME = Pattern.compile("^[A-Za-z0-9 _-]{1,12}$");

	private final String sessionId;
	private final String displayName;
	private final String accountType;
	private final String profileType;
	private final String pluginVersion;
	private final String runeLiteVersion;
	private final int gameRevision;

	static SyncContext capture(Client client, UUID sessionId)
	{
		Objects.requireNonNull(client, "client");
		Objects.requireNonNull(sessionId, "sessionId");
		Player localPlayer = Objects.requireNonNull(client.getLocalPlayer(), "local player");
		String name = Objects.requireNonNull(localPlayer.getName(), "display name")
			.replace('\u00a0', ' ');
		if (!DISPLAY_NAME.matcher(name).matches())
		{
			throw new IllegalStateException("Unsupported display name");
		}

		return new SyncContext(
			sessionId.toString(),
			name,
			accountType(client.getVarbitValue(VarbitID.IRONMAN)),
			profileType(client.getWorldType()),
			PLUGIN_VERSION,
			RuneLiteProperties.getVersion(),
			client.getRevision());
	}

	SyncContext(
		String sessionId,
		String displayName,
		String accountType,
		String profileType,
		String pluginVersion,
		String runeLiteVersion,
		int gameRevision)
	{
		this.sessionId = Objects.requireNonNull(sessionId, "sessionId");
		this.displayName = Objects.requireNonNull(displayName, "displayName");
		this.accountType = Objects.requireNonNull(accountType, "accountType");
		this.profileType = Objects.requireNonNull(profileType, "profileType");
		this.pluginVersion = Objects.requireNonNull(pluginVersion, "pluginVersion");
		this.runeLiteVersion = Objects.requireNonNull(runeLiteVersion, "runeLiteVersion");
		this.gameRevision = gameRevision;
	}

	String getSessionId()
	{
		return sessionId;
	}

	String getDisplayName()
	{
		return displayName;
	}

	String getAccountType()
	{
		return accountType;
	}

	String getProfileType()
	{
		return profileType;
	}

	String getPluginVersion()
	{
		return pluginVersion;
	}

	String getRuneLiteVersion()
	{
		return runeLiteVersion;
	}

	int getGameRevision()
	{
		return gameRevision;
	}

	static String accountType(int accountType)
	{
		switch (accountType)
		{
			case 0:
				return "regular";
			case 1:
			case 4:
				return "ironman";
			case 2:
				return "ultimate";
			case 3:
			case 5:
				return "hardcore";
			default:
				throw new IllegalStateException("Unsupported account type");
		}
	}

	static String profileType(EnumSet<WorldType> worldTypes)
	{
		if (worldTypes != null && worldTypes.contains(WorldType.DEADMAN))
		{
			return "deadman";
		}
		if (worldTypes != null && worldTypes.contains(WorldType.SEASONAL))
		{
			return "league";
		}
		return "standard";
	}
}

package com.runeglass.runelite;

import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.Base64;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class AppearanceMeshEncoderTest
{
	@Test
	public void encodesVersionedMeshAndOmitsHiddenFaces()
	{
		AppearanceMeshEncoder.EncodedMesh mesh = AppearanceMeshEncoder.encode(
			new float[]{-10, 10, 0},
			new float[]{0, 0, -20},
			new float[]{0, 0, 5},
			new int[]{0, 0},
			new int[]{1, 1},
			new int[]{2, 2},
			new int[]{4_000, 4_100},
			new int[]{4_001, 4_101},
			new int[]{4_002, -2},
			new byte[]{0, 0},
			new byte[]{1, 1},
			new short[]{-1, -1},
			new int[]{0, 512, 768},
			new int[]{0, 1, 2, 3, 4},
			0);

		assertEquals(3, mesh.getVertexCount());
		assertEquals(1, mesh.getFaceCount());
		assertArrayEquals(new int[]{0, 512, 768}, mesh.getEquipment());
		assertFalse(mesh.hasTextures());
		assertEquals(43, mesh.getModelHash().length());

		byte[] bytes = Base64.getDecoder().decode(mesh.getMeshBase64());
		ByteBuffer buffer = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);
		assertEquals('R', buffer.get());
		assertEquals('G', buffer.get());
		assertEquals('M', buffer.get());
		assertEquals('1', buffer.get());
		assertEquals(1, buffer.get());
		assertEquals(0, buffer.get());
		assertEquals(3, buffer.getShort());
		assertEquals(3, buffer.getInt());
		assertEquals(1, buffer.getInt());
	}

	@Test
	public void recordsTexturedFacesWithoutEmbeddingGameTextures()
	{
		AppearanceMeshEncoder.EncodedMesh mesh = AppearanceMeshEncoder.encode(
			new float[]{0, 10, 0},
			new float[]{0, 0, -10},
			new float[]{0, 0, 0},
			new int[]{0},
			new int[]{1},
			new int[]{2},
			new int[]{1},
			new int[]{1},
			new int[]{1},
			null,
			null,
			new short[]{42},
			new int[]{0},
			new int[]{0, 0, 0, 0, 0},
			1);

		assertTrue(mesh.hasTextures());
	}

	@Test
	public void rejectsOutOfBoundsGeometryAndComposition()
	{
		assertThrows(IllegalArgumentException.class, () -> AppearanceMeshEncoder.encode(
			new float[]{0, 10, 0},
			new float[]{0, 0, -10},
			new float[]{0, 0, 0},
			new int[]{0},
			new int[]{1},
			new int[]{3},
			new int[]{1},
			new int[]{1},
			new int[]{1},
			null,
			null,
			null,
			new int[]{0},
			new int[]{0, 0, 0, 0, 0},
			0));
	}
}

package com.runeglass.runelite;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.Arrays;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class BirdHouseClientTest
{
	private static final String RAW_CREDENTIAL = "rrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrr";
	private static final String CONNECTION_ID = "pcn_ccccccccccccccccccccccccccccccccccccccccccc";
	private static final Instant OBSERVED_AT = Instant.parse("2026-08-28T10:00:00Z");
	private static final String SESSION_ID = "0b54873e-c169-4de7-9bd0-abc879f84d2f";

	private MockWebServer server;
	private ScheduledExecutorService executor;
	private SemanticSnapshotClient<BirdHouseSnapshot> client;

	@Before
	public void setUp() throws IOException
	{
		server = new MockWebServer();
		server.start();
		executor = Executors.newSingleThreadScheduledExecutor();
		client = new SemanticSnapshotClient<>(
			new OkHttpClient(),
			new Gson(),
			executor,
			server.url("/"),
			Clock.fixed(OBSERVED_AT, ZoneOffset.UTC),
			1,
			() -> 0L,
			"runelite/v1/bird-houses",
			(context, connectionId, snapshot) -> SemanticSnapshotPayload.create(
				context,
				connectionId,
				snapshot.getSnapshotId(),
				snapshot.getObservedAt(),
				"houses",
				snapshot.getHouses()));
	}

	@After
	public void tearDown() throws IOException
	{
		client.discard();
		executor.shutdownNow();
		server.shutdown();
	}

	@Test
	public void sendsAnExactAuthenticatedSemanticSnapshot() throws Exception
	{
		server.enqueue(accepted());
		CountDownLatch accepted = new CountDownLatch(1);
		AtomicReference<SemanticSnapshotClient.Failure> failure = new AtomicReference<>();
		client.connect(credentials(), context(), listener(accepted, failure));
		assertTrue(client.publish(snapshot()));

		RecordedRequest request = server.takeRequest(3, TimeUnit.SECONDS);
		assertEquals("/runelite/v1/bird-houses", request.getPath());
		assertEquals("Bearer " + RAW_CREDENTIAL, request.getHeader("Authorization"));
		String bodyText = request.getBody().readUtf8();
		assertFalse(bodyText.contains(RAW_CREDENTIAL));
		JsonObject body = new JsonParser().parse(bodyText).getAsJsonObject();
		assertExactKeys(
			body,
			"protocolVersion",
			"snapshotId",
			"connectionId",
			"sessionId",
			"observedAt",
			"client",
			"character",
			"houses");
		assertEquals(CONNECTION_ID, body.get("connectionId").getAsString());
		assertEquals(4, body.getAsJsonArray("houses").size());
		JsonObject empty = body.getAsJsonArray("houses").get(0).getAsJsonObject();
		assertExactKeys(empty, "space", "state");
		JsonObject seeded = body.getAsJsonArray("houses").get(2).getAsJsonObject();
		assertExactKeys(seeded, "space", "state", "tier", "startedAt", "readyAt");

		assertTrue(accepted.await(3, TimeUnit.SECONDS));
		assertNull(failure.get());
	}

	@Test
	public void discardDropsAnUnsentObservation()
	{
		client.connect(credentials(), context(), listener(new CountDownLatch(0), new AtomicReference<>()));
		client.discard();
		assertFalse(client.publish(snapshot()));
	}

	private static PairingClient.Credentials credentials()
	{
		return new PairingClient.Credentials(CONNECTION_ID, RAW_CREDENTIAL);
	}

	private static SyncContext context()
	{
		return new SyncContext(
			SESSION_ID,
			"Iron Jeromey",
			"ironman",
			"standard",
			"1.1.0",
			"1.12.36",
			231);
	}

	private static BirdHouseSnapshot snapshot()
	{
		return new BirdHouseSnapshot(
			"018f35d8-29e4-7cc2-8a58-f9a76b1f3d91",
			OBSERVED_AT,
			Arrays.asList(
				new BirdHouseObservation(BirdHouseSpace.MEADOW_NORTH, BirdHouseState.EMPTY, null, null, null),
				new BirdHouseObservation(BirdHouseSpace.MEADOW_SOUTH, BirdHouseState.BUILT, BirdHouseTier.YEW, null, null),
				new BirdHouseObservation(
					BirdHouseSpace.VALLEY_NORTH,
					BirdHouseState.SEEDED,
					BirdHouseTier.REDWOOD,
					OBSERVED_AT,
					OBSERVED_AT.plusSeconds(50 * 60)),
				new BirdHouseObservation(BirdHouseSpace.VALLEY_SOUTH, BirdHouseState.SEEDED, BirdHouseTier.MAGIC, null, null)));
	}

	private static SemanticSnapshotClient.Listener listener(
		CountDownLatch accepted,
		AtomicReference<SemanticSnapshotClient.Failure> failure)
	{
		return new SemanticSnapshotClient.Listener()
		{
			@Override
			public void onAccepted(Instant serverTime)
			{
				accepted.countDown();
			}

			@Override
			public void onRetryScheduled()
			{
			}

			@Override
			public void onFailure(SemanticSnapshotClient.Failure value)
			{
				failure.set(value);
			}
		};
	}

	private static MockResponse accepted()
	{
		return new MockResponse()
			.setResponseCode(200)
			.setHeader("Content-Type", "application/json")
			.setBody("{\"protocolVersion\":1,\"status\":\"accepted\","
				+ "\"serverTime\":\"2026-08-28T10:00:01Z\","
				+ "\"nextUploadAfterSeconds\":5}");
	}

	private static void assertExactKeys(JsonObject body, String... keys)
	{
		assertEquals(keys.length, body.size());
		for (String key : keys)
		{
			assertTrue(body.has(key));
		}
	}
}

package com.runeglass.runelite;

import java.time.Instant;
import java.util.Optional;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class BirdHouseSnapshotReducerTest
{
	private static final Instant OBSERVED_AT = Instant.parse("2026-08-28T10:00:00Z");

	@Test
	public void emitsOnlySemanticStateForAllFourSpaces()
	{
		BirdHouseSnapshotReducer reducer = new BirdHouseSnapshotReducer();
		int[] states = new int[]{0, 20, 27, 24};
		reducer.observe(14650, 0, states, OBSERVED_AT);
		BirdHouseSnapshot snapshot = reducer
			.observe(14650, 0, states, OBSERVED_AT.plusSeconds(1))
			.orElseThrow(AssertionError::new);

		assertEquals(4, snapshot.getHouses().size());
		assertEquals("meadow_north", snapshot.getHouses().get(0).getSpace());
		assertEquals("empty", snapshot.getHouses().get(0).getState());
		assertNull(snapshot.getHouses().get(0).getTier());
		assertEquals("built", snapshot.getHouses().get(1).getState());
		assertEquals("yew", snapshot.getHouses().get(1).getTier());
		assertEquals("seeded", snapshot.getHouses().get(2).getState());
		assertEquals("redwood", snapshot.getHouses().get(2).getTier());
		assertNull(snapshot.getHouses().get(2).getReadyAt());
	}

	@Test
	public void estimatesReadinessOnlyWhenTheSeededTransitionWasObserved()
	{
		BirdHouseSnapshotReducer reducer = new BirdHouseSnapshotReducer();
		reducer.observe(14650, 0, new int[]{0, 20, 26, 23}, OBSERVED_AT);
		reducer.observe(14650, 0, new int[]{0, 20, 26, 23}, OBSERVED_AT.plusSeconds(1));

		Instant seededAt = OBSERVED_AT.plusSeconds(10);
		BirdHouseSnapshot snapshot = reducer
			.observe(14650, 0, new int[]{0, 20, 27, 24}, seededAt)
			.orElseThrow(AssertionError::new);

		assertEquals(seededAt.toString(), snapshot.getHouses().get(2).getStartedAt());
		assertEquals(
			seededAt.plusSeconds(50 * 60).toString(),
			snapshot.getHouses().get(2).getReadyAt());
		assertEquals(seededAt.toString(), snapshot.getHouses().get(3).getStartedAt());
	}

	@Test
	public void ignoresUnchangedOffIslandAndLikelyUninitializedObservations()
	{
		BirdHouseSnapshotReducer reducer = new BirdHouseSnapshotReducer();
		int[] built = new int[]{20, 20, 20, 20};
		assertFalse(reducer.observe(12850, 0, built, OBSERVED_AT).isPresent());
		assertFalse(reducer.observe(14650, 0, built, OBSERVED_AT).isPresent());
		assertTrue(reducer.observe(14650, 0, built, OBSERVED_AT.plusSeconds(1)).isPresent());
		assertFalse(reducer.observe(14650, 0, built, OBSERVED_AT.plusSeconds(2)).isPresent());
		assertFalse(reducer.observe(
			14650,
			0,
			new int[]{0, 0, 0, 0},
			OBSERVED_AT.plusSeconds(3)).isPresent());
	}

	@Test
	public void requiresAStableInitialObservationBeforePublishing()
	{
		BirdHouseSnapshotReducer reducer = new BirdHouseSnapshotReducer();
		assertFalse(reducer.observe(
			14650,
			0,
			new int[]{16, 16, 16, 16},
			OBSERVED_AT).isPresent());
		assertFalse(reducer.observe(
			14650,
			0,
			new int[]{15, 15, 15, 15},
			OBSERVED_AT.plusSeconds(1)).isPresent());

		BirdHouseSnapshot snapshot = reducer.observe(
			14650,
			0,
			new int[]{15, 15, 15, 15},
			OBSERVED_AT.plusSeconds(2))
			.orElseThrow(AssertionError::new);
		for (BirdHouseObservation house : snapshot.getHouses())
		{
			assertEquals("seeded", house.getState());
			assertNull(house.getStartedAt());
			assertNull(house.getReadyAt());
		}
	}

	@Test
	public void rejectsUnknownVarpsWithoutReplacingTheLastValidState()
	{
		BirdHouseSnapshotReducer reducer = new BirdHouseSnapshotReducer();
		reducer.observe(14650, 0, new int[]{20, 20, 20, 20}, OBSERVED_AT);
		reducer.observe(14650, 0, new int[]{20, 20, 20, 20}, OBSERVED_AT.plusSeconds(1));
		Optional<BirdHouseSnapshot> invalid = reducer.observe(
			14650,
			0,
			new int[]{28, 20, 20, 20},
			OBSERVED_AT.plusSeconds(2));

		assertFalse(invalid.isPresent());
		assertFalse(reducer.observe(
			14650,
			0,
			new int[]{20, 20, 20, 20},
			OBSERVED_AT.plusSeconds(3)).isPresent());
	}
}

package com.runeglass.runelite;

import com.google.gson.Gson;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.PosixFilePermission;
import java.util.EnumSet;
import java.util.Set;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

public class ConnectionStateStoreTest
{
	private static final String CONNECTION_ID = "pcn_ccccccccccccccccccccccccccccccccccccccccccc";
	private static final String CREDENTIAL = "rrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrr";

	@Rule
	public final TemporaryFolder temporaryFolder = new TemporaryFolder();

	@Test
	public void savesAndRestoresOneProfileScopedState() throws Exception
	{
		Path profiles = temporaryFolder.newFolder("profiles").toPath();
		ConnectionStateStore store = new ConnectionStateStore(profiles, "profile-one", new Gson());
		assertTrue(store.save(
			new PairingClient.Credentials(CONNECTION_ID, CREDENTIAL),
			BigInteger.valueOf(42)));

		ConnectionStateStore.State state = store.load().orElseThrow(AssertionError::new);
		assertEquals(CONNECTION_ID, state.getCredentials().getConnectionId());
		assertEquals(CREDENTIAL, state.getCredentials().getRawCredential());
		assertEquals(BigInteger.valueOf(42), state.getNextSequence());
		assertTrue(Files.exists(store.getStateFile()));
		assertFalse(Files.exists(store.getStateFile().resolveSibling(ConnectionStateStore.TEMP_FILE_NAME)));
	}

	@Test
	public void separatesProfilesWithoutUsingRawProfileKeys() throws Exception
	{
		Path profiles = temporaryFolder.newFolder("profiles").toPath();
		ConnectionStateStore first = new ConnectionStateStore(profiles, "profile-one", new Gson());
		ConnectionStateStore second = new ConnectionStateStore(profiles, "profile-two", new Gson());

		assertTrue(first.save(
			new PairingClient.Credentials(CONNECTION_ID, CREDENTIAL),
			BigInteger.ONE));

		assertNotEquals(first.getStateFile(), second.getStateFile());
		assertFalse(first.getStateFile().toString().contains("profile-one"));
		assertFalse(second.load().isPresent());
	}

	@Test
	public void malformedStateIsDiscarded() throws Exception
	{
		Path profiles = temporaryFolder.newFolder("profiles").toPath();
		ConnectionStateStore store = new ConnectionStateStore(profiles, "profile-one", new Gson());
		Files.createDirectories(store.getStateFile().getParent());
		Files.write(
			store.getStateFile(),
			"{\"version\":1,\"connectionId\":\"wrong\",\"credential\":\"wrong\",\"nextSequence\":\"1\"}"
				.getBytes(StandardCharsets.UTF_8));

		assertFalse(store.load().isPresent());
		assertFalse(Files.exists(store.getStateFile()));
	}

	@Test
	public void appliesOwnerOnlyPermissionsWhenSupported() throws Exception
	{
		Path profiles = temporaryFolder.newFolder("profiles").toPath();
		ConnectionStateStore store = new ConnectionStateStore(profiles, "profile-one", new Gson());
		assertTrue(store.save(
			new PairingClient.Credentials(CONNECTION_ID, CREDENTIAL),
			BigInteger.ONE));

		try
		{
			Set<PosixFilePermission> filePermissions = Files.getPosixFilePermissions(store.getStateFile());
			assertEquals(EnumSet.of(
				PosixFilePermission.OWNER_READ,
				PosixFilePermission.OWNER_WRITE), filePermissions);
			Set<PosixFilePermission> directoryPermissions = Files.getPosixFilePermissions(
				store.getStateFile().getParent());
			assertEquals(EnumSet.of(
				PosixFilePermission.OWNER_READ,
				PosixFilePermission.OWNER_WRITE,
				PosixFilePermission.OWNER_EXECUTE), directoryPermissions);
		}
		catch (UnsupportedOperationException ignored)
		{
			assertTrue(Files.exists(store.getStateFile()));
		}
	}
}

package com.runeglass.runelite;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
